INSERT OR IGNORE INTO rulesets (_id, sharedAllowancePence, startDate, endDate, notes) VALUES ('2017/2018', 2000000, '2017-04-06', '2018-04-05', NULL);
UPDATE rulesets SET sharedAllowancePence = 2000000, startDate = '2017-04-06', endDate = '2018-04-05', notes = NULL WHERE _id = '2017/2018';
INSERT OR IGNORE INTO rulesets (_id, sharedAllowancePence, startDate, endDate, notes) VALUES ('2018/2019', 2000000, '2018-04-06', '2019-04-05', 'The Junior ISA allowance was increased by £132/year (£11/month) in line with inflation.');
UPDATE rulesets SET sharedAllowancePence = 2000000, startDate = '2018-04-06', endDate = '2019-04-05', notes = 'The Junior ISA allowance was increased by £132/year (£11/month) in line with inflation.' WHERE _id = '2018/2019';
INSERT OR IGNORE INTO rulesets (_id, sharedAllowancePence, startDate, endDate, notes) VALUES ('2019/2020', 2000000, '2019-04-06', '2020-04-05', 'The Junior ISA allowance was increased by £108/year (£9/month) in line with inflation.');
UPDATE rulesets SET sharedAllowancePence = 2000000, startDate = '2019-04-06', endDate = '2020-04-05', notes = 'The Junior ISA allowance was increased by £108/year (£9/month) in line with inflation.' WHERE _id = '2019/2020';
INSERT OR IGNORE INTO rulesets (_id, sharedAllowancePence, startDate, endDate, notes) VALUES ('2020/2021', 2000000, '2020-04-06', '2021-04-05', 'The Junior ISA allowance was increased by £4,632/year (£386/month). The LISA withdrawal charge was reduced from 25% to 20% for withdrawals made between 6th March 2020 and 5th April 2021.');
UPDATE rulesets SET sharedAllowancePence = 2000000, startDate = '2020-04-06', endDate = '2021-04-05', notes = 'The Junior ISA allowance was increased by £4,632/year (£386/month). The LISA withdrawal charge was reduced from 25% to 20% for withdrawals made between 6th March 2020 and 5th April 2021.' WHERE _id = '2020/2021';
INSERT OR IGNORE INTO rulesets (_id, sharedAllowancePence, startDate, endDate, notes) VALUES ('2021/2022', 2000000, '2021-04-06', '2022-04-05', 'There were no changes to ISAs this year.');
UPDATE rulesets SET sharedAllowancePence = 2000000, startDate = '2021-04-06', endDate = '2022-04-05', notes = 'There were no changes to ISAs this year.' WHERE _id = '2021/2022';
INSERT OR IGNORE INTO rulesets (_id, sharedAllowancePence, startDate, endDate, notes) VALUES ('2022/2023', 2000000, '2022-04-06', '2023-04-05', 'There were no changes to ISAs this year.');
UPDATE rulesets SET sharedAllowancePence = 2000000, startDate = '2022-04-06', endDate = '2023-04-05', notes = 'There were no changes to ISAs this year.' WHERE _id = '2022/2023';
INSERT OR IGNORE INTO rulesets (_id, sharedAllowancePence, startDate, endDate, notes) VALUES ('2023/2024', 2000000, '2023-04-06', '2024-04-05', 'There were no changes to ISAs this year.');
UPDATE rulesets SET sharedAllowancePence = 2000000, startDate = '2023-04-06', endDate = '2024-04-05', notes = 'There were no changes to ISAs this year.' WHERE _id = '2023/2024';
INSERT OR IGNORE INTO rulesets (_id, sharedAllowancePence, startDate, endDate, notes) VALUES ('2024/2025', 2000000, '2024-04-06', '2025-04-05', 'Fractional share contracts were added to the eligble investments within Stocks and Shares, Junior and Lifetime ISAs. It is now permissible to open and pay into multiple of the same type of ISAs in the same year, with Lifetime ISAs and Junior ISAs excepted. The minimum age for opening an ISA increased from 16 to 18. Partial transfers of ISA contributions were introduced. There were no changes to allowances for ISAs and allowances for all ISA types were frozen until the 2030/2031 tax year.');
UPDATE rulesets SET sharedAllowancePence = 2000000, startDate = '2024-04-06', endDate = '2025-04-05', notes = 'Fractional share contracts were added to the eligble investments within Stocks and Shares, Junior and Lifetime ISAs. It is now permissible to open and pay into multiple of the same type of ISAs in the same year, with Lifetime ISAs and Junior ISAs excepted. The minimum age for opening an ISA increased from 16 to 18. Partial transfers of ISA contributions were introduced. There were no changes to allowances for ISAs and allowances for all ISA types were frozen until the 2030/2031 tax year.' WHERE _id = '2024/2025';
INSERT OR IGNORE INTO rulesets (_id, sharedAllowancePence, startDate, endDate, notes) VALUES ('2025/2026', 2000000, '2025-04-06', '2026-04-05', 'Long-Term Asset Funds were added to the eligible investments within Innovative Fund ISAs. A National Insurance number is now required to be provided to open an ISA, unless ineligible. There were no changes to allowances.');
UPDATE rulesets SET sharedAllowancePence = 2000000, startDate = '2025-04-06', endDate = '2026-04-05', notes = 'Long-Term Asset Funds were added to the eligible investments within Innovative Fund ISAs. A National Insurance number is now required to be provided to open an ISA, unless ineligible. There were no changes to allowances.' WHERE _id = '2025/2026';
INSERT OR IGNORE INTO productTypes (_id, name, introducedWithRuleset, removedWithRuleset, shortDescription, longDescription) VALUES ('CASH', 'Cash ISA', '2008/2009', NULL, 'Earn interest on cash tax-free', 'A deposit account, where your cash is guaranteed. The rules for accessing the cash once deposited may differ by account.');
UPDATE productTypes SET name = 'Cash ISA', introducedWithRuleset = '2008/2009', removedWithRuleset = NULL, shortDescription = 'Earn interest on cash tax-free', longDescription = 'A deposit account, where your cash is guaranteed. The rules for accessing the cash once deposited may differ by account.' WHERE _id = 'CASH';
INSERT OR IGNORE INTO productTypes (_id, name, introducedWithRuleset, removedWithRuleset, shortDescription, longDescription) VALUES ('STOCKS_AND_SHARES', 'Stocks & Shares ISA', '2008/2009', NULL, 'Invest without paying tax on gains', 'A number of investment structures in a tax-free wrapper. Income and gains from the investments in the accounts are not subject to dividend, income or capital gains taxes.');
UPDATE productTypes SET name = 'Stocks & Shares ISA', introducedWithRuleset = '2008/2009', removedWithRuleset = NULL, shortDescription = 'Invest without paying tax on gains', longDescription = 'A number of investment structures in a tax-free wrapper. Income and gains from the investments in the accounts are not subject to dividend, income or capital gains taxes.' WHERE _id = 'STOCKS_AND_SHARES';
INSERT OR IGNORE INTO productTypes (_id, name, introducedWithRuleset, removedWithRuleset, shortDescription, longDescription) VALUES ('INNOVATIVE_FINANCE', 'Innovative Finance ISA', '2016/2017', NULL, 'Profit from peer-to-peer lending, tax-free', 'An account with a peer-to-peer lending provider with a tax-free wrapper. Interest earned from providing high-risk loans are earned tax-free.');
UPDATE productTypes SET name = 'Innovative Finance ISA', introducedWithRuleset = '2016/2017', removedWithRuleset = NULL, shortDescription = 'Profit from peer-to-peer lending, tax-free', longDescription = 'An account with a peer-to-peer lending provider with a tax-free wrapper. Interest earned from providing high-risk loans are earned tax-free.' WHERE _id = 'INNOVATIVE_FINANCE';
INSERT OR IGNORE INTO productTypes (_id, name, introducedWithRuleset, removedWithRuleset, shortDescription, longDescription) VALUES ('LIFETIME', 'Lifetime ISA', '2017/2018', NULL, 'Get rewarded for saving for your first home (or retirement)', 'A Cash or Stocks & Shares ISA with age and spend limitations, in exchange for a 25% bonus provided by the Government when withdrawing for the purchase of a first home, after turning 60 years old, when diagnosed with a terminal illness.');
UPDATE productTypes SET name = 'Lifetime ISA', introducedWithRuleset = '2017/2018', removedWithRuleset = NULL, shortDescription = 'Get rewarded for saving for your first home (or retirement)', longDescription = 'A Cash or Stocks & Shares ISA with age and spend limitations, in exchange for a 25% bonus provided by the Government when withdrawing for the purchase of a first home, after turning 60 years old, when diagnosed with a terminal illness.' WHERE _id = 'LIFETIME';
INSERT OR IGNORE INTO productTypes (_id, name, introducedWithRuleset, removedWithRuleset, shortDescription, longDescription) VALUES ('JUNIOR', 'Junior ISA', '2011/2012', NULL, 'Save for your child''s future', 'A Cash or Stocks & Shares ISA held in a child''s name. Money cannot be withdrawn until they turn 18, or in if diagnosed with a terminal illness.');
UPDATE productTypes SET name = 'Junior ISA', introducedWithRuleset = '2011/2012', removedWithRuleset = NULL, shortDescription = 'Save for your child''s future', longDescription = 'A Cash or Stocks & Shares ISA held in a child''s name. Money cannot be withdrawn until they turn 18, or in if diagnosed with a terminal illness.' WHERE _id = 'JUNIOR';
INSERT OR IGNORE INTO productTypes (_id, name, introducedWithRuleset, removedWithRuleset, shortDescription, longDescription) VALUES ('HELP_TO_BUY', 'Help To Buy ISA', '2015/2016', '2019/2020', 'Save up for your first home and earn a government bonus', 'A Cash ISA with a monthly top-up restriction that, if used towards the purchase of your first home, will be topped up with a 25% government bonus.');
UPDATE productTypes SET name = 'Help To Buy ISA', introducedWithRuleset = '2015/2016', removedWithRuleset = '2019/2020', shortDescription = 'Save up for your first home and earn a government bonus', longDescription = 'A Cash ISA with a monthly top-up restriction that, if used towards the purchase of your first home, will be topped up with a 25% government bonus.' WHERE _id = 'HELP_TO_BUY';
